int a = 10;
int b = 20;

// Full-Expression Boundary 1: Statement End
a = b + 5;

// Full-Expression Boundary 2: Initialization
int c = a * 2;


struct T { ~T(); };
T make_T();

// T() temporary destroyed here (end of full-expression)
(void)make_T();

// Temporaries bound to const ref live until scope exit
const T& ref = make_T();


// Full-Expression Boundary 3: Condition/Initializer
if (int result = calculate(); result > 0) {
    // result exists inside scope
}

// Full-Expression Boundary 4: For loop controls
for (init(); condition(); step()) {
    break;
}
